// =================== CHEMISTRY QUESTION BANK ===================
// 150 questions across 10 topics, each with Easy/Medium/Hard difficulty
// Format: { id, topic, difficulty, question, options[], answer (0-indexed), explanation, funFact }

const QUESTIONS = [

    // =================== 1. ATOMIC STRUCTURE (15) ===================
    // Easy (5)
    { id: 1, topic: "Atomic Structure", difficulty: "Easy", question: "What is the center of an atom called?", options: ["Electron cloud", "Nucleus", "Proton shell", "Neutron layer"], answer: 1, explanation: "The nucleus is the dense, central part of the atom containing protons and neutrons.", funFact: "The nucleus is about 100,000 times smaller than the atom itself!" },
    { id: 2, topic: "Atomic Structure", difficulty: "Easy", question: "Which subatomic particle has a negative charge?", options: ["Proton", "Neutron", "Electron", "Positron"], answer: 2, explanation: "Electrons carry a negative charge of -1 and orbit the nucleus in electron shells.", funFact: "An electron weighs about 1/1836 the mass of a proton." },
    { id: 3, topic: "Atomic Structure", difficulty: "Easy", question: "What does the atomic number represent?", options: ["Number of neutrons", "Number of protons", "Number of electrons", "Mass number"], answer: 1, explanation: "The atomic number (Z) is the number of protons in the nucleus, which defines the element.", funFact: "The atomic number was first determined by Henry Moseley in 1913 using X-ray spectroscopy." },
    { id: 4, topic: "Atomic Structure", difficulty: "Easy", question: "Which particle has no electrical charge?", options: ["Proton", "Electron", "Neutron", "Ion"], answer: 2, explanation: "Neutrons are electrically neutral particles found in the nucleus alongside protons.", funFact: "Free neutrons outside the nucleus decay with a half-life of about 10 minutes." },
    { id: 5, topic: "Atomic Structure", difficulty: "Easy", question: "What are atoms of the same element with different numbers of neutrons called?", options: ["Ions", "Isotopes", "Isomers", "Allotropes"], answer: 1, explanation: "Isotopes have the same number of protons but different numbers of neutrons, giving them different mass numbers.", funFact: "Hydrogen has three isotopes: protium, deuterium, and tritium." },

    // Medium (5)
    { id: 6, topic: "Atomic Structure", difficulty: "Medium", question: "Who proposed the plum pudding model of the atom?", options: ["Ernest Rutherford", "Niels Bohr", "J.J. Thomson", "John Dalton"], answer: 2, explanation: "J.J. Thomson proposed the plum pudding model after discovering the electron in 1897.", funFact: "Thomson won the Nobel Prize for discovering the electron, and his son won one for proving electrons are waves!" },
    { id: 7, topic: "Atomic Structure", difficulty: "Medium", question: "What is the maximum number of electrons in the third shell (n=3)?", options: ["8", "18", "32", "2"], answer: 1, explanation: "The maximum electrons in a shell is given by 2n². For n=3: 2(3²) = 18.", funFact: "The formula 2n² was derived from quantum mechanics by Wolfgang Pauli." },
    { id: 8, topic: "Atomic Structure", difficulty: "Medium", question: "Which experiment led to the discovery of the nucleus?", options: ["Cathode ray experiment", "Oil drop experiment", "Gold foil experiment", "Photoelectric experiment"], answer: 2, explanation: "Rutherford's gold foil experiment (1911) showed most alpha particles passed through, but some bounced back, revealing a dense nucleus.", funFact: "Only about 1 in 8000 alpha particles bounced back in Rutherford's experiment." },
    { id: 9, topic: "Atomic Structure", difficulty: "Medium", question: "What is the Heisenberg Uncertainty Principle about?", options: ["Energy conservation", "Electron spin", "Position and momentum of particles", "Nuclear decay rates"], answer: 2, explanation: "The Heisenberg Uncertainty Principle states that you cannot simultaneously know both the exact position and exact momentum of a particle.", funFact: "Heisenberg was only 25 when he formulated this groundbreaking principle." },
    { id: 10, topic: "Atomic Structure", difficulty: "Medium", question: "How many orbitals are in a d subshell?", options: ["1", "3", "5", "7"], answer: 2, explanation: "A d subshell has 5 orbitals (ml = -2, -1, 0, +1, +2), each holding up to 2 electrons for a total of 10.", funFact: "The d orbitals have complex shapes including cloverleaf patterns." },

    // Hard (5)
    { id: 11, topic: "Atomic Structure", difficulty: "Hard", question: "What is the electron configuration of Cr (Z=24)?", options: ["[Ar] 3d⁴ 4s²", "[Ar] 3d⁵ 4s¹", "[Ar] 3d³ 4s² 4p¹", "[Ar] 3d⁶"], answer: 1, explanation: "Chromium has an anomalous configuration [Ar] 3d⁵ 4s¹ because a half-filled d subshell provides extra stability.", funFact: "Copper also has this anomaly: [Ar] 3d¹⁰ 4s¹ instead of [Ar] 3d⁹ 4s²." },
    { id: 12, topic: "Atomic Structure", difficulty: "Hard", question: "What quantum number describes the shape of an orbital?", options: ["Principal (n)", "Angular momentum (l)", "Magnetic (ml)", "Spin (ms)"], answer: 1, explanation: "The angular momentum quantum number (l) determines the shape: l=0 is s (sphere), l=1 is p (dumbbell), l=2 is d (cloverleaf).", funFact: "The letter designations s, p, d, f come from spectroscopy terms: sharp, principal, diffuse, and fundamental." },
    { id: 13, topic: "Atomic Structure", difficulty: "Hard", question: "According to the Aufbau principle, which subshell fills before 3d?", options: ["3p", "4s", "4p", "3s"], answer: 1, explanation: "The 4s subshell (n+l=4+0=4) fills before 3d (n+l=3+2=5) because it has a lower n+l value.", funFact: "The Aufbau principle comes from the German word 'Aufbau' meaning 'building up'." },
    { id: 14, topic: "Atomic Structure", difficulty: "Hard", question: "What is the de Broglie wavelength equation?", options: ["λ = h/mv", "λ = mc²", "λ = hν", "λ = E/h"], answer: 0, explanation: "de Broglie proposed that all matter has wave properties, with wavelength λ = h/mv (h = Planck's constant, m = mass, v = velocity).", funFact: "de Broglie's PhD thesis proposing this idea was so revolutionary that it was sent to Einstein for review." },
    { id: 15, topic: "Atomic Structure", difficulty: "Hard", question: "What is the ground state term symbol for nitrogen (Z=7)?", options: ["²P₃/₂", "⁴S₃/₂", "³P₂", "²D₅/₂"], answer: 1, explanation: "Nitrogen has 3 unpaired electrons in 2p orbitals (Hund's rule), giving S=3/2, L=0, J=3/2, hence ⁴S₃/₂.", funFact: "Term symbols encode all the angular momentum information of an atom's electron configuration." },

    // =================== 2. PERIODIC TABLE (15) ===================
    // Easy (5)
    { id: 16, topic: "Periodic Table", difficulty: "Easy", question: "Which element has the symbol 'O'?", options: ["Osmium", "Oxygen", "Oganesson", "Gold"], answer: 1, explanation: "Oxygen is a nonmetal with the symbol O, atomic number 8.", funFact: "Oxygen makes up about 21% of Earth's atmosphere and 65% of the human body by mass." },
    { id: 17, topic: "Periodic Table", difficulty: "Easy", question: "How many elements are in the modern periodic table?", options: ["92", "103", "118", "120"], answer: 2, explanation: "As of now, 118 elements have been confirmed, from Hydrogen (1) to Oganesson (118).", funFact: "Elements 113-118 were all confirmed between 2002 and 2010." },
    { id: 18, topic: "Periodic Table", difficulty: "Easy", question: "Which group contains the noble gases?", options: ["Group 1", "Group 7", "Group 17", "Group 18"], answer: 3, explanation: "Noble gases (He, Ne, Ar, Kr, Xe, Rn, Og) are in Group 18, known for their full valence shells and chemical inertness.", funFact: "Noble gases were once called 'inert gases' until Neil Bartlett made the first noble gas compound (XePtF₆) in 1962." },
    { id: 19, topic: "Periodic Table", difficulty: "Easy", question: "What is the lightest element?", options: ["Helium", "Lithium", "Hydrogen", "Carbon"], answer: 2, explanation: "Hydrogen is the lightest and most abundant element in the universe, with an atomic mass of ~1.008 u.", funFact: "About 75% of all matter in the universe is hydrogen." },
    { id: 20, topic: "Periodic Table", difficulty: "Easy", question: "Which element is a liquid metal at room temperature?", options: ["Iron", "Mercury", "Lead", "Tin"], answer: 1, explanation: "Mercury (Hg) is the only metal that is liquid at standard room temperature (25°C).", funFact: "Mercury's chemical symbol Hg comes from 'hydrargyrum', Greek for 'liquid silver'." },

    // Medium (5)
    { id: 21, topic: "Periodic Table", difficulty: "Medium", question: "What trend describes atomic radius across a period (left to right)?", options: ["Increases", "Decreases", "Stays the same", "Increases then decreases"], answer: 1, explanation: "Across a period, increasing nuclear charge pulls electrons closer, decreasing atomic radius despite adding electrons to the same shell.", funFact: "Francium is theoretically the largest atom, but it's so radioactive that its radius has never been directly measured." },
    { id: 22, topic: "Periodic Table", difficulty: "Medium", question: "What is the most electronegative element?", options: ["Oxygen", "Chlorine", "Fluorine", "Nitrogen"], answer: 2, explanation: "Fluorine has the highest electronegativity (3.98 on the Pauling scale) of any element.", funFact: "Fluorine is so reactive that it even reacts with glass, and must be stored in special containers." },
    { id: 23, topic: "Periodic Table", difficulty: "Medium", question: "Which block of elements includes the lanthanides?", options: ["s-block", "p-block", "d-block", "f-block"], answer: 3, explanation: "Lanthanides (elements 57-71) and actinides (89-103) are in the f-block, filling 4f and 5f orbitals respectively.", funFact: "Lanthanides are also called 'rare earth elements' even though some aren't particularly rare." },
    { id: 24, topic: "Periodic Table", difficulty: "Medium", question: "Which element has the highest first ionization energy?", options: ["Fluorine", "Helium", "Neon", "Hydrogen"], answer: 1, explanation: "Helium has the highest first ionization energy (2372 kJ/mol) due to its very stable 1s² configuration and small atomic radius.", funFact: "Helium was first discovered in the Sun's spectrum before it was found on Earth." },
    { id: 25, topic: "Periodic Table", difficulty: "Medium", question: "What property do metalloids exhibit?", options: ["Only metallic properties", "Only nonmetallic properties", "Properties of both metals and nonmetals", "No distinctive properties"], answer: 2, explanation: "Metalloids (like Si, Ge, As) exhibit intermediate properties — they can conduct electricity partially, making them ideal semiconductors.", funFact: "Silicon, a metalloid, is the backbone of modern computing and electronics." },

    // Hard (5)
    { id: 26, topic: "Periodic Table", difficulty: "Hard", question: "Which element has the highest electron affinity?", options: ["Fluorine", "Chlorine", "Bromine", "Oxygen"], answer: 1, explanation: "Chlorine has the highest electron affinity (-349 kJ/mol), higher than fluorine due to electron-electron repulsion in fluorine's small 2p orbitals.", funFact: "This is one of the few cases where the general periodic trend (increasing up a group) breaks down." },
    { id: 27, topic: "Periodic Table", difficulty: "Hard", question: "What is the diagonal relationship in the periodic table?", options: ["Elements in the same group have similar properties", "Elements diagonally adjacent have similar properties", "Elements across a period have identical properties", "Elements in the same block react identically"], answer: 1, explanation: "Diagonally adjacent elements (e.g., Li-Mg, Be-Al, B-Si) show similar properties due to comparable charge density and electronegativity.", funFact: "Lithium behaves more like magnesium than sodium in many reactions." },
    { id: 28, topic: "Periodic Table", difficulty: "Hard", question: "Why does the 3d series show irregular ionization energies?", options: ["Nuclear charge variations", "Exchange energy and orbital pairing effects", "Relativistic effects", "Shielding is constant"], answer: 1, explanation: "Irregularities in 3d ionization energies arise from exchange energy stabilization (half/fully filled subshells) and electron pairing energy costs.", funFact: "The extra stability of d⁵ and d¹⁰ configurations affects the chemistry of Mn and Zn compounds." },
    { id: 29, topic: "Periodic Table", difficulty: "Hard", question: "What is the lanthanide contraction?", options: ["Expansion of lanthanide atoms", "Decrease in atomic/ionic radii across the lanthanide series", "Contraction of electron shells under pressure", "Reduction of nuclear charge"], answer: 1, explanation: "Poor shielding by 4f electrons causes a steady decrease in atomic and ionic radii across the lanthanide series (La to Lu).", funFact: "The lanthanide contraction makes Hf almost the same size as Zr, despite being one period lower." },
    { id: 30, topic: "Periodic Table", difficulty: "Hard", question: "Which element exhibits the inert pair effect most prominently?", options: ["Carbon", "Silicon", "Tin", "Thallium"], answer: 3, explanation: "Thallium (Tl) strongly exhibits the inert pair effect, where the 6s² electrons resist participation in bonding, making Tl⁺ more stable than Tl³⁺.", funFact: "The inert pair effect increases down a group and is linked to relativistic contraction of s orbitals." },

    // =================== 3. CHEMICAL BONDING (15) ===================
    // Easy (5)
    { id: 31, topic: "Chemical Bonding", difficulty: "Easy", question: "What type of bond involves the sharing of electron pairs?", options: ["Ionic", "Covalent", "Metallic", "Hydrogen"], answer: 1, explanation: "Covalent bonds form when two atoms share one or more pairs of electrons.", funFact: "The word 'covalent' comes from Latin 'co-' (together) and 'valent' (strength)." },
    { id: 32, topic: "Chemical Bonding", difficulty: "Easy", question: "What type of bond forms between a metal and a nonmetal?", options: ["Covalent", "Ionic", "Metallic", "Van der Waals"], answer: 1, explanation: "Ionic bonds form when a metal transfers electrons to a nonmetal, creating oppositely charged ions that attract.", funFact: "Table salt (NaCl) is the most common example of an ionic compound." },
    { id: 33, topic: "Chemical Bonding", difficulty: "Easy", question: "How many covalent bonds does carbon typically form?", options: ["2", "3", "4", "6"], answer: 2, explanation: "Carbon has 4 valence electrons and forms 4 covalent bonds to achieve a stable octet.", funFact: "Carbon's ability to form 4 bonds and chain with itself is why it's the basis of all organic life." },
    { id: 34, topic: "Chemical Bonding", difficulty: "Easy", question: "What is a bond between hydrogen and a highly electronegative atom like O, N, or F called?", options: ["Ionic bond", "Covalent bond", "Hydrogen bond", "Metallic bond"], answer: 2, explanation: "A hydrogen bond is a strong intermolecular force between a hydrogen atom bonded to F, O, or N and another electronegative atom.", funFact: "Hydrogen bonding is why water has an unusually high boiling point for its molecular weight." },
    { id: 35, topic: "Chemical Bonding", difficulty: "Easy", question: "What is the octet rule?", options: ["Atoms gain 8 protons for stability", "Atoms tend to gain, lose, or share electrons to have 8 valence electrons", "Molecules must have 8 atoms", "Bonds require 8 electrons total"], answer: 1, explanation: "The octet rule states that atoms tend to form bonds to achieve 8 electrons in their valence shell, like noble gases.", funFact: "Hydrogen is an exception — it only needs 2 electrons (a 'duet') for stability." },

    // Medium (5)
    { id: 36, topic: "Chemical Bonding", difficulty: "Medium", question: "What is the bond angle in a tetrahedral molecule?", options: ["90°", "109.5°", "120°", "180°"], answer: 1, explanation: "Tetrahedral geometry has bond angles of 109.5°, minimizing electron pair repulsion (VSEPR theory).", funFact: "Methane (CH₄) is a perfect tetrahedral molecule." },
    { id: 37, topic: "Chemical Bonding", difficulty: "Medium", question: "What type of bond has the greatest difference in electronegativity?", options: ["Nonpolar covalent", "Polar covalent", "Ionic", "Metallic"], answer: 2, explanation: "Ionic bonds have electronegativity differences > 1.7. Polar covalent: 0.4-1.7. Nonpolar covalent: < 0.4.", funFact: "The Pauling electronegativity scale was invented by Linus Pauling, one of only two people to win two unshared Nobel Prizes." },
    { id: 38, topic: "Chemical Bonding", difficulty: "Medium", question: "What is a coordinate (dative) covalent bond?", options: ["A bond where electrons are shared equally", "A bond where both electrons come from one atom", "A bond between two metals", "A triple bond"], answer: 1, explanation: "In a coordinate bond, one atom donates both electrons in the shared pair. Example: NH₃ donating to H⁺ to form NH₄⁺.", funFact: "Coordinate bonds are crucial in transition metal complex chemistry." },
    { id: 39, topic: "Chemical Bonding", difficulty: "Medium", question: "According to VSEPR theory, what shape does a molecule with 3 bonding pairs and 1 lone pair have?", options: ["Tetrahedral", "Trigonal pyramidal", "Trigonal planar", "Bent"], answer: 1, explanation: "3 bonding pairs + 1 lone pair gives a trigonal pyramidal shape (like NH₃). The lone pair pushes bonds closer together.", funFact: "The bond angle in NH₃ is 107° instead of 109.5° because lone pairs repel more strongly." },
    { id: 40, topic: "Chemical Bonding", difficulty: "Medium", question: "Which intermolecular force is the weakest?", options: ["Hydrogen bonding", "Dipole-dipole", "London dispersion forces", "Ion-dipole"], answer: 2, explanation: "London dispersion forces (induced dipole-induced dipole) are the weakest intermolecular forces, arising from temporary electron distribution asymmetries.", funFact: "Despite being weak individually, London forces are why nonpolar molecules like I₂ can be solid at room temperature." },

    // Hard (5)
    { id: 41, topic: "Chemical Bonding", difficulty: "Hard", question: "What hybridization does the central atom in XeF₄ have?", options: ["sp³", "sp³d", "sp³d²", "sp²"], answer: 2, explanation: "XeF₄ has 4 bonding pairs + 2 lone pairs = 6 electron domains, requiring sp³d² hybridization (octahedral electron geometry, square planar shape).", funFact: "XeF₄ was one of the first noble gas compounds ever made, in 1962." },
    { id: 42, topic: "Chemical Bonding", difficulty: "Hard", question: "What is the bond order of O₂ according to Molecular Orbital Theory?", options: ["1", "1.5", "2", "3"], answer: 2, explanation: "O₂ has bond order = (bonding electrons - antibonding electrons)/2 = (10-6)/2 = 2. It also has 2 unpaired electrons, making it paramagnetic.", funFact: "MO theory correctly predicts O₂ is paramagnetic, which Lewis structures cannot explain." },
    { id: 43, topic: "Chemical Bonding", difficulty: "Hard", question: "Which compound violates the octet rule by having an expanded octet?", options: ["BF₃", "PCl₅", "NO₂", "CO"], answer: 1, explanation: "PCl₅ has 5 bonding pairs around phosphorus (10 electrons), exceeding the octet. This is possible because P can use its 3d orbitals.", funFact: "Only elements in period 3 and below can have expanded octets, as they have accessible d orbitals." },
    { id: 44, topic: "Chemical Bonding", difficulty: "Hard", question: "What is resonance energy?", options: ["Energy released during bond formation", "Difference between actual energy and most stable resonance structure", "Energy needed to break all bonds", "Energy of electron transitions"], answer: 1, explanation: "Resonance energy is the stabilization energy — the difference between the actual molecule's energy and the energy of the most stable single Lewis structure.", funFact: "Benzene's resonance energy is about 150 kJ/mol, making it much more stable than predicted." },
    { id: 45, topic: "Chemical Bonding", difficulty: "Hard", question: "In MO theory, what happens when two atomic orbitals combine?", options: ["They form one molecular orbital", "They form a bonding and an antibonding orbital", "They remain unchanged", "They form three molecular orbitals"], answer: 1, explanation: "Two atomic orbitals combine to form two molecular orbitals: one bonding (lower energy) and one antibonding (higher energy).", funFact: "Antibonding orbitals are denoted with an asterisk (σ*, π*) and have a node between the nuclei." },

    // =================== 4. STOICHIOMETRY (15) ===================
    // Easy (5)
    { id: 46, topic: "Stoichiometry", difficulty: "Easy", question: "What is the molar mass of water (H₂O)?", options: ["16 g/mol", "18 g/mol", "20 g/mol", "36 g/mol"], answer: 1, explanation: "H₂O: 2(1.008) + 16.00 = 18.015 g/mol ≈ 18 g/mol.", funFact: "One mole of water is only about 18 mL — roughly a tablespoon!" },
    { id: 47, topic: "Stoichiometry", difficulty: "Easy", question: "What is Avogadro's number?", options: ["6.022 × 10²⁰", "6.022 × 10²³", "6.022 × 10²⁶", "3.022 × 10²³"], answer: 1, explanation: "Avogadro's number (6.022 × 10²³) is the number of particles (atoms, molecules, ions) in one mole of a substance.", funFact: "If you had a mole of pennies and distributed them equally, every person on Earth would have about $1 trillion." },
    { id: 48, topic: "Stoichiometry", difficulty: "Easy", question: "In the equation 2H₂ + O₂ → 2H₂O, what is the mole ratio of H₂ to O₂?", options: ["1:1", "2:1", "1:2", "2:2"], answer: 1, explanation: "The coefficients show 2 moles of H₂ react with 1 mole of O₂, giving a 2:1 mole ratio.", funFact: "This reaction is so exothermic that it powered the Space Shuttle's main engines." },
    { id: 49, topic: "Stoichiometry", difficulty: "Easy", question: "What is the law of conservation of mass?", options: ["Mass increases in reactions", "Mass decreases in reactions", "Mass is neither created nor destroyed in reactions", "Mass is converted to energy"], answer: 2, explanation: "The law of conservation of mass states that total mass of reactants equals total mass of products in a chemical reaction.", funFact: "Antoine Lavoisier is credited with establishing this law through careful experiments in the 1770s." },
    { id: 50, topic: "Stoichiometry", difficulty: "Easy", question: "What does a balanced chemical equation show?", options: ["Only the products of a reaction", "Equal numbers of each type of atom on both sides", "The speed of a reaction", "The color change in a reaction"], answer: 1, explanation: "A balanced equation has equal numbers of each element on both sides, satisfying the law of conservation of mass.", funFact: "Balancing equations was first systematized by Jeremias Benjamin Richter in 1792." },

    // Medium (5)
    { id: 51, topic: "Stoichiometry", difficulty: "Medium", question: "If 4.0 g of H₂ reacts with excess O₂, how many grams of H₂O are produced?", options: ["18 g", "36 g", "9 g", "72 g"], answer: 1, explanation: "4.0 g H₂ = 2 moles H₂. From 2H₂ + O₂ → 2H₂O, 2 mol H₂ produces 2 mol H₂O = 2 × 18 = 36 g.", funFact: "Hydrogen is the cleanest fuel — its only combustion product is water." },
    { id: 52, topic: "Stoichiometry", difficulty: "Medium", question: "What is the limiting reagent?", options: ["The reagent present in excess", "The reagent that is completely consumed first", "The most expensive reagent", "The catalyst"], answer: 1, explanation: "The limiting reagent is completely consumed in a reaction and determines the maximum amount of product formed.", funFact: "In baking, flour is often the limiting 'reagent' that determines how many cookies you can make." },
    { id: 53, topic: "Stoichiometry", difficulty: "Medium", question: "What is the empirical formula of a compound with 40% C, 6.7% H, and 53.3% O?", options: ["C₂H₄O₂", "CH₂O", "C₃H₆O₃", "CHO"], answer: 1, explanation: "Converting to moles: C: 40/12=3.33, H: 6.7/1=6.7, O: 53.3/16=3.33. Ratio = 1:2:1, so empirical formula = CH₂O.", funFact: "CH₂O is the empirical formula for both formaldehyde and glucose — very different substances!" },
    { id: 54, topic: "Stoichiometry", difficulty: "Medium", question: "If the percent yield of a reaction is 80% and the theoretical yield is 50 g, what is the actual yield?", options: ["40 g", "62.5 g", "50 g", "45 g"], answer: 0, explanation: "Actual yield = (percent yield × theoretical yield) / 100 = (80 × 50) / 100 = 40 g.", funFact: "In pharmaceutical manufacturing, percent yields below 50% are common for complex drug molecules." },
    { id: 55, topic: "Stoichiometry", difficulty: "Medium", question: "At STP, what volume does 1 mole of an ideal gas occupy?", options: ["11.2 L", "22.4 L", "44.8 L", "1.0 L"], answer: 1, explanation: "At Standard Temperature and Pressure (0°C, 1 atm), one mole of an ideal gas occupies 22.4 liters.", funFact: "This is roughly the volume of 3 basketballs!" },

    // Hard (5)
    { id: 56, topic: "Stoichiometry", difficulty: "Hard", question: "In a reaction A + 2B → C, if 5 mol of A and 8 mol of B are mixed, what is the limiting reagent?", options: ["A", "B", "Both are limiting", "Neither is limiting"], answer: 1, explanation: "For 5 mol A, you need 10 mol B. Only 8 mol B is available, so B is the limiting reagent. Only 4 mol A will react.", funFact: "Identifying the limiting reagent is one of the most practical skills in laboratory chemistry." },
    { id: 57, topic: "Stoichiometry", difficulty: "Hard", question: "A 10.0 g sample of a hydrate loses 3.6 g of water when heated. If the anhydrous salt is MgSO₄ (120 g/mol), what is the formula of the hydrate?", options: ["MgSO₄·H₂O", "MgSO₄·2H₂O", "MgSO₄·4H₂O", "MgSO₄·7H₂O"], answer: 2, explanation: "Moles of MgSO₄ = 6.4/120 = 0.0533. Moles of H₂O = 3.6/18 = 0.2. Ratio = 0.2/0.0533 ≈ 3.75 ≈ 4. So MgSO₄·4H₂O.", funFact: "Epsom salt (MgSO₄·7H₂O) is a common hydrate used in bath soaks." },
    { id: 58, topic: "Stoichiometry", difficulty: "Hard", question: "What is the molarity of a solution made by dissolving 11.7 g NaCl (58.5 g/mol) in enough water to make 500 mL of solution?", options: ["0.2 M", "0.4 M", "0.5 M", "1.0 M"], answer: 1, explanation: "Moles = 11.7/58.5 = 0.2 mol. Molarity = 0.2 mol / 0.5 L = 0.4 M.", funFact: "Normal saline solution used in hospitals is 0.154 M NaCl." },
    { id: 59, topic: "Stoichiometry", difficulty: "Hard", question: "A 2.50 g sample of an unknown gas occupies 1.12 L at STP. What is its molar mass?", options: ["25 g/mol", "40 g/mol", "50 g/mol", "56 g/mol"], answer: 2, explanation: "At STP, moles = V/22.4 = 1.12/22.4 = 0.05 mol. Molar mass = mass/moles = 2.50/0.05 = 50 g/mol.", funFact: "This could be methyl formate (CH₃OCHO), a naturally occurring ester." },
    { id: 60, topic: "Stoichiometry", difficulty: "Hard", question: "In a back-titration, 25.0 mL of 0.1 M HCl is added to an antacid tablet. The excess HCl requires 12.0 mL of 0.1 M NaOH. How many moles of HCl were neutralized by the antacid?", options: ["0.0013 mol", "0.0025 mol", "0.0013 mol", "0.0037 mol"], answer: 0, explanation: "Total HCl = 0.025 × 0.1 = 0.0025 mol. Excess HCl = 0.012 × 0.1 = 0.0012 mol. Neutralized = 0.0025 - 0.0012 = 0.0013 mol.", funFact: "Back-titration is used when the analyte is insoluble or reacts too slowly for direct titration." },

    // =================== 5. THERMODYNAMICS (15) ===================
    // Easy (5)
    { id: 61, topic: "Thermodynamics", difficulty: "Easy", question: "What is an exothermic reaction?", options: ["A reaction that absorbs heat", "A reaction that releases heat", "A reaction at constant temperature", "A reaction that produces gas"], answer: 1, explanation: "Exothermic reactions release energy to the surroundings, resulting in a negative enthalpy change (ΔH < 0).", funFact: "Your body's metabolism is exothermic — it's how you stay warm!" },
    { id: 62, topic: "Thermodynamics", difficulty: "Easy", question: "What is the SI unit of energy?", options: ["Calorie", "Joule", "Watt", "Newton"], answer: 1, explanation: "The Joule (J) is the SI unit of energy. 1 calorie = 4.184 joules.", funFact: "One joule is the energy needed to lift a small apple (100 g) one meter against gravity." },
    { id: 63, topic: "Thermodynamics", difficulty: "Easy", question: "What does the First Law of Thermodynamics state?", options: ["Entropy always increases", "Energy cannot be created or destroyed", "Heat flows from hot to cold", "Absolute zero is unattainable"], answer: 1, explanation: "The First Law states that energy is conserved — it can be converted between forms but the total energy in an isolated system remains constant.", funFact: "This is also known as the law of conservation of energy." },
    { id: 64, topic: "Thermodynamics", difficulty: "Easy", question: "What is the standard enthalpy of formation of an element in its standard state?", options: ["100 kJ/mol", "1 kJ/mol", "0 kJ/mol", "-100 kJ/mol"], answer: 2, explanation: "By definition, the standard enthalpy of formation of any element in its most stable allotrope at standard conditions is exactly 0.", funFact: "Graphite (not diamond) is carbon's standard state because it's thermodynamically more stable." },
    { id: 65, topic: "Thermodynamics", difficulty: "Easy", question: "What happens to temperature during a phase change?", options: ["It increases", "It decreases", "It remains constant", "It fluctuates"], answer: 2, explanation: "During a phase change, the temperature remains constant as energy goes into breaking or forming intermolecular bonds rather than increasing kinetic energy.", funFact: "This is why ice water stays at 0°C until all the ice melts, even with continuous heating." },

    // Medium (5)
    { id: 66, topic: "Thermodynamics", difficulty: "Medium", question: "What is Hess's Law?", options: ["Enthalpy depends on temperature only", "Total enthalpy change is independent of the pathway", "Entropy always increases", "Free energy equals zero at equilibrium"], answer: 1, explanation: "Hess's Law states that the total enthalpy change for a reaction is the same regardless of whether it occurs in one step or multiple steps.", funFact: "Hess published this law in 1840, and it's a direct consequence of enthalpy being a state function." },
    { id: 67, topic: "Thermodynamics", difficulty: "Medium", question: "What is entropy?", options: ["A measure of heat content", "A measure of disorder or randomness", "A measure of free energy", "A measure of reaction rate"], answer: 1, explanation: "Entropy (S) is a measure of the disorder or number of microstates available to a system. Higher entropy = more disorder.", funFact: "Ludwig Boltzmann's famous equation S = k ln W is engraved on his tombstone in Vienna." },
    { id: 68, topic: "Thermodynamics", difficulty: "Medium", question: "What is the Gibbs free energy equation?", options: ["ΔG = ΔH + TΔS", "ΔG = ΔH - TΔS", "ΔG = ΔH × TΔS", "ΔG = ΔH / TΔS"], answer: 1, explanation: "The Gibbs free energy equation ΔG = ΔH - TΔS determines spontaneity: ΔG < 0 means the reaction is spontaneous.", funFact: "Josiah Willard Gibbs was so modest that most of his colleagues didn't realize his genius during his lifetime." },
    { id: 69, topic: "Thermodynamics", difficulty: "Medium", question: "A reaction with ΔH = -100 kJ and ΔS = +50 J/K is spontaneous at:", options: ["All temperatures", "Only high temperatures", "Only low temperatures", "No temperature"], answer: 0, explanation: "When ΔH < 0 and ΔS > 0, ΔG = ΔH - TΔS is always negative, so the reaction is spontaneous at all temperatures.", funFact: "Combustion reactions are a real-world example of this type — exothermic with increasing disorder." },
    { id: 70, topic: "Thermodynamics", difficulty: "Medium", question: "What is the specific heat capacity of water?", options: ["1.0 J/g·°C", "2.1 J/g·°C", "4.18 J/g·°C", "0.45 J/g·°C"], answer: 2, explanation: "Water has an unusually high specific heat capacity of 4.18 J/g·°C, meaning it can absorb a lot of heat with little temperature change.", funFact: "Water's high specific heat is why coastal climates are more moderate than inland ones." },

    // Hard (5)
    { id: 71, topic: "Thermodynamics", difficulty: "Hard", question: "For the reaction N₂(g) + 3H₂(g) → 2NH₃(g), what is ΔS likely to be?", options: ["Positive", "Negative", "Zero", "Cannot determine"], answer: 1, explanation: "4 moles of gas become 2 moles of gas, so the system becomes more ordered (fewer gas molecules = less randomness). ΔS < 0.", funFact: "This is the Haber process, which produces over 150 million tonnes of ammonia annually." },
    { id: 72, topic: "Thermodynamics", difficulty: "Hard", question: "What is the Carnot efficiency formula?", options: ["η = 1 - Tc/Th", "η = Tc/Th", "η = 1 + Tc/Th", "η = Th/Tc"], answer: 0, explanation: "The maximum theoretical efficiency of a heat engine is η = 1 - Tc/Th, where T values are in Kelvin.", funFact: "No real engine can achieve Carnot efficiency — it's a theoretical upper limit." },
    { id: 73, topic: "Thermodynamics", difficulty: "Hard", question: "For a system at equilibrium, what is the value of ΔG?", options: ["-RT ln K", "ΔH - TΔS", "0", "1"], answer: 2, explanation: "At equilibrium, ΔG = 0. The system is at its minimum free energy and has no net driving force in either direction.", funFact: "The relationship ΔG° = -RT ln K connects standard free energy to the equilibrium constant." },
    { id: 74, topic: "Thermodynamics", difficulty: "Hard", question: "What is the Third Law of Thermodynamics?", options: ["Energy is conserved", "Entropy increases in spontaneous processes", "The entropy of a perfect crystal at 0 K is zero", "Free energy determines spontaneity"], answer: 2, explanation: "The Third Law states that as temperature approaches absolute zero, the entropy of a perfect crystal approaches zero.", funFact: "This law implies that absolute zero (0 K) can never actually be reached, only approached." },
    { id: 75, topic: "Thermodynamics", difficulty: "Hard", question: "Calculate ΔH for C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l) given bond energies aren't available, but ΔHf° values are: C₂H₅OH = -277, CO₂ = -393.5, H₂O = -285.8 kJ/mol.", options: ["-1366.6 kJ", "-956.3 kJ", "-500 kJ", "-1100 kJ"], answer: 0, explanation: "ΔH = ΣΔHf°(products) - ΣΔHf°(reactants) = [2(-393.5) + 3(-285.8)] - [-277 + 0] = -787 - 857.4 + 277 = -1367.4 ≈ -1366.6 kJ.", funFact: "This is the combustion of ethanol — the same reaction that powers ethanol fuel vehicles." },

    // =================== 6. ACID-BASE CHEMISTRY (15) ===================
    // Easy (5)
    { id: 76, topic: "Acid-Base Chemistry", difficulty: "Easy", question: "What is the pH of pure water at 25°C?", options: ["0", "7", "14", "1"], answer: 1, explanation: "Pure water has a pH of 7 at 25°C because [H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M, and pH = -log(10⁻⁷) = 7.", funFact: "The pH scale was invented by Danish chemist Søren Sørensen in 1909 while working at the Carlsberg brewery!" },
    { id: 77, topic: "Acid-Base Chemistry", difficulty: "Easy", question: "Which of these is a strong acid?", options: ["CH₃COOH (acetic acid)", "HCl (hydrochloric acid)", "H₂CO₃ (carbonic acid)", "HF (hydrofluoric acid)"], answer: 1, explanation: "HCl is a strong acid that completely dissociates in water. The other options are weak acids that only partially dissociate.", funFact: "There are only 7 common strong acids: HCl, HBr, HI, HNO₃, H₂SO₄, HClO₃, and HClO₄." },
    { id: 78, topic: "Acid-Base Chemistry", difficulty: "Easy", question: "What color does litmus paper turn in an acid?", options: ["Blue", "Red", "Green", "Yellow"], answer: 1, explanation: "Blue litmus paper turns red in acidic solutions (pH < 7). Red litmus turns blue in basic solutions.", funFact: "Litmus is derived from lichens and has been used as a pH indicator since the 14th century." },
    { id: 79, topic: "Acid-Base Chemistry", difficulty: "Easy", question: "What is formed when an acid reacts with a base?", options: ["Another acid", "A salt and water", "A gas", "An oxide"], answer: 1, explanation: "Neutralization reaction: acid + base → salt + water. Example: HCl + NaOH → NaCl + H₂O.", funFact: "Antacid tablets work by neutralizing excess stomach acid (HCl) with bases like CaCO₃." },
    { id: 80, topic: "Acid-Base Chemistry", difficulty: "Easy", question: "What is the pH range for acidic solutions?", options: ["0-7", "7-14", "0-14", "7 only"], answer: 0, explanation: "Acidic solutions have pH < 7, neutral is exactly 7, and basic (alkaline) solutions have pH > 7.", funFact: "Stomach acid has a pH of about 1.5-3.5, strong enough to dissolve some metals!" },

    // Medium (5)
    { id: 81, topic: "Acid-Base Chemistry", difficulty: "Medium", question: "According to Brønsted-Lowry theory, what is an acid?", options: ["Electron pair acceptor", "Proton donor", "Proton acceptor", "Hydroxide donor"], answer: 1, explanation: "A Brønsted-Lowry acid is a proton (H⁺) donor. This definition is broader than Arrhenius, applying to non-aqueous solvents too.", funFact: "Brønsted and Lowry independently proposed this theory in the same year, 1923." },
    { id: 82, topic: "Acid-Base Chemistry", difficulty: "Medium", question: "What is a buffer solution?", options: ["A very concentrated acid", "A solution that resists pH changes", "A neutral solution", "A solution with pH 7"], answer: 1, explanation: "A buffer solution resists changes in pH when small amounts of acid or base are added. It typically contains a weak acid and its conjugate base.", funFact: "Blood is buffered at pH 7.4 by the carbonic acid/bicarbonate system. A change of just 0.3 units can be fatal." },
    { id: 83, topic: "Acid-Base Chemistry", difficulty: "Medium", question: "What is the Ka of a strong acid?", options: ["Very small (<<1)", "Exactly 1", "Very large (>>1)", "Zero"], answer: 2, explanation: "Strong acids have very large Ka values (effectively infinity) because they completely dissociate in water.", funFact: "Fluoroantimonic acid (HSbF₆) is the world's strongest superacid, about 10¹⁶ times stronger than sulfuric acid." },
    { id: 84, topic: "Acid-Base Chemistry", difficulty: "Medium", question: "What is the relationship between pH and pOH at 25°C?", options: ["pH + pOH = 7", "pH + pOH = 14", "pH × pOH = 14", "pH - pOH = 14"], answer: 1, explanation: "At 25°C, pH + pOH = 14 because Kw = [H⁺][OH⁻] = 1.0 × 10⁻¹⁴, and -log(Kw) = pKw = 14.", funFact: "This relationship changes with temperature — at body temperature (37°C), pKw ≈ 13.6." },
    { id: 85, topic: "Acid-Base Chemistry", difficulty: "Medium", question: "What is the conjugate base of H₂SO₄?", options: ["SO₄²⁻", "HSO₄⁻", "H₃SO₄⁺", "H₂SO₃"], answer: 1, explanation: "When H₂SO₄ donates a proton, it becomes HSO₄⁻ (hydrogen sulfate), its conjugate base.", funFact: "HSO₄⁻ is itself a weak acid that can donate its remaining proton to form SO₄²⁻." },

    // Hard (5)
    { id: 86, topic: "Acid-Base Chemistry", difficulty: "Hard", question: "What is the pH of a 0.01 M solution of a weak acid with Ka = 1.0 × 10⁻⁴?", options: ["2.0", "3.0", "4.0", "5.0"], answer: 1, explanation: "For weak acid: [H⁺] = √(Ka × C) = √(10⁻⁴ × 0.01) = √(10⁻⁶) = 10⁻³ M. pH = -log(10⁻³) = 3.0.", funFact: "This approximation works well when Ka/C < 0.05 (the 5% rule)." },
    { id: 87, topic: "Acid-Base Chemistry", difficulty: "Hard", question: "What is the Henderson-Hasselbalch equation?", options: ["pH = pKa + log([HA]/[A⁻])", "pH = pKa + log([A⁻]/[HA])", "pH = Ka × [A⁻]/[HA]", "pH = -log(Ka × [HA])"], answer: 1, explanation: "The Henderson-Hasselbalch equation: pH = pKa + log([A⁻]/[HA]) relates buffer pH to the ratio of conjugate base to weak acid concentrations.", funFact: "This equation is essential in pharmacology for predicting drug absorption based on pH." },
    { id: 88, topic: "Acid-Base Chemistry", difficulty: "Hard", question: "According to Lewis theory, what is an acid?", options: ["Proton donor", "Proton acceptor", "Electron pair acceptor", "Electron pair donor"], answer: 2, explanation: "A Lewis acid is an electron pair acceptor. This is the broadest acid-base definition, encompassing species like BF₃ and metal cations.", funFact: "G.N. Lewis, who proposed this theory, also gave us Lewis dot structures and the concept of covalent bonding." },
    { id: 89, topic: "Acid-Base Chemistry", difficulty: "Hard", question: "At the half-equivalence point of a weak acid titration, pH equals:", options: ["7", "pKa", "pKb", "0"], answer: 1, explanation: "At the half-equivalence point, exactly half the acid is neutralized, so [HA] = [A⁻], and pH = pKa + log(1) = pKa.", funFact: "This property makes the half-equivalence point the most useful for determining Ka experimentally." },
    { id: 90, topic: "Acid-Base Chemistry", difficulty: "Hard", question: "What is the pH at the equivalence point of a strong acid-weak base titration?", options: ["7", "Less than 7", "Greater than 7", "Depends on the indicator"], answer: 1, explanation: "At the equivalence point, the solution contains only the conjugate acid of the weak base, which hydrolyzes to make the solution acidic (pH < 7).", funFact: "This is why methyl orange (transition pH 3.1-4.4) is a better indicator for this type of titration than phenolphthalein." },

    // =================== 7. ORGANIC CHEMISTRY (15) ===================
    // Easy (5)
    { id: 91, topic: "Organic Chemistry", difficulty: "Easy", question: "What is the simplest alkane?", options: ["Ethane", "Methane", "Propane", "Butane"], answer: 1, explanation: "Methane (CH₄) is the simplest alkane with just one carbon atom and four hydrogen atoms.", funFact: "Methane is the main component of natural gas and is produced by cows — about 70-120 kg per cow per year!" },
    { id: 92, topic: "Organic Chemistry", difficulty: "Easy", question: "What is the general formula for alkanes?", options: ["CₙH₂ₙ", "CₙH₂ₙ₊₂", "CₙH₂ₙ₋₂", "CₙHₙ"], answer: 1, explanation: "Alkanes follow the formula CₙH₂ₙ₊₂ where n is the number of carbon atoms. They are saturated hydrocarbons.", funFact: "The longest alkane ever synthesized has 390 carbon atoms!" },
    { id: 93, topic: "Organic Chemistry", difficulty: "Easy", question: "What functional group defines an alcohol?", options: ["-COOH", "-OH", "-CHO", "-NH₂"], answer: 1, explanation: "Alcohols contain a hydroxyl (-OH) group bonded to a carbon atom.", funFact: "The alcohol in beverages (ethanol) was one of the first organic compounds made by humans — through fermentation." },
    { id: 94, topic: "Organic Chemistry", difficulty: "Easy", question: "What type of bond is present in alkenes that is absent in alkanes?", options: ["Single bond", "Double bond", "Triple bond", "Ionic bond"], answer: 1, explanation: "Alkenes contain at least one C=C double bond, making them unsaturated hydrocarbons, unlike saturated alkanes.", funFact: "Ethylene (ethene) is a plant hormone that causes fruit ripening!" },
    { id: 95, topic: "Organic Chemistry", difficulty: "Easy", question: "What is the name of the compound CH₃OH?", options: ["Ethanol", "Methanol", "Propanol", "Butanol"], answer: 1, explanation: "CH₃OH is methanol (methyl alcohol), the simplest alcohol with just one carbon.", funFact: "Methanol is extremely toxic — as little as 10 mL can cause blindness, and 30 mL can be fatal." },

    // Medium (5)
    { id: 96, topic: "Organic Chemistry", difficulty: "Medium", question: "What is an isomer?", options: ["A different element with the same mass", "A compound with the same formula but different structure", "A radioactive form of a molecule", "A mirror image that is superimposable"], answer: 1, explanation: "Isomers are compounds with the same molecular formula but different structural arrangements of atoms.", funFact: "Glucose and fructose (both C₆H₁₂O₆) are isomers with vastly different sweetness levels." },
    { id: 97, topic: "Organic Chemistry", difficulty: "Medium", question: "What type of reaction converts an alkene to an alkane?", options: ["Oxidation", "Hydrogenation", "Dehydration", "Cracking"], answer: 1, explanation: "Hydrogenation adds H₂ across a double bond (C=C → C-C) using a metal catalyst like Pt, Pd, or Ni.", funFact: "Margarine is made by partial hydrogenation of vegetable oils — converting liquid oils to solid fats." },
    { id: 98, topic: "Organic Chemistry", difficulty: "Medium", question: "What is the IUPAC name for CH₃CH₂CH₂OH?", options: ["Methanol", "Ethanol", "Propan-1-ol", "Butan-1-ol"], answer: 2, explanation: "A 3-carbon chain with -OH on the first carbon is propan-1-ol (or 1-propanol). The common name is n-propyl alcohol.", funFact: "IUPAC naming was standardized so chemists worldwide could unambiguously communicate about compounds." },
    { id: 99, topic: "Organic Chemistry", difficulty: "Medium", question: "What functional group does a carboxylic acid contain?", options: ["-OH", "-CHO", "-COOH", "-CO-"], answer: 2, explanation: "Carboxylic acids contain the -COOH (carboxyl) group — a combination of a carbonyl and hydroxyl group.", funFact: "Acetic acid (CH₃COOH) in vinegar and citric acid in lemons are everyday carboxylic acids." },
    { id: 100, topic: "Organic Chemistry", difficulty: "Medium", question: "What is polymerization?", options: ["Breaking large molecules into small ones", "Combining small molecules (monomers) into large chains (polymers)", "Dissolving polymers in solvents", "Crystallizing organic compounds"], answer: 1, explanation: "Polymerization joins many small monomer molecules to form a long chain polymer. Example: ethene → polyethylene.", funFact: "About 8.3 billion tonnes of plastic have been produced since the 1950s." },

    // Hard (5)
    { id: 101, topic: "Organic Chemistry", difficulty: "Hard", question: "What is Markovnikov's rule?", options: ["The halogen adds to the more substituted carbon", "The hydrogen adds to the carbon with more hydrogens", "Double bonds always break homolytically", "Substitution always favors the primary carbon"], answer: 1, explanation: "Markovnikov's rule: In the addition of HX to an alkene, the hydrogen adds to the carbon with more hydrogen atoms (less substituted), and X adds to the more substituted carbon.", funFact: "Anti-Markovnikov addition was discovered by Morris Kharasch in 1933 using peroxide catalysts." },
    { id: 102, topic: "Organic Chemistry", difficulty: "Hard", question: "What determines whether a substitution reaction is SN1 or SN2?", options: ["Temperature only", "Substrate structure, nucleophile strength, and solvent", "Only the leaving group", "Only the catalyst"], answer: 1, explanation: "SN2 is favored with primary substrates, strong nucleophiles, and polar aprotic solvents. SN1 is favored with tertiary substrates and polar protic solvents.", funFact: "SN2 reactions invert the stereochemistry at the carbon (Walden inversion), like an umbrella flipping in the wind." },
    { id: 103, topic: "Organic Chemistry", difficulty: "Hard", question: "What is a chiral center?", options: ["A carbon with a double bond", "A carbon bonded to four different groups", "Any sp² hybridized carbon", "A carbon in a ring structure"], answer: 1, explanation: "A chiral center (stereocenter) is a carbon atom bonded to four different substituents, creating non-superimposable mirror images (enantiomers).", funFact: "Your hands are chiral — they are mirror images but cannot be superimposed. This is why it's called 'chirality' (Greek: cheir = hand)." },
    { id: 104, topic: "Organic Chemistry", difficulty: "Hard", question: "What is the Grignard reagent?", options: ["RMgX (organomagnesium halide)", "RLi (organolithium)", "R₂CuLi (organocuprate)", "RZnX (organozinc)"], answer: 0, explanation: "A Grignard reagent (RMgX) is formed by reacting an alkyl halide with magnesium in dry ether. It acts as a strong nucleophile and base.", funFact: "Victor Grignard won the 1912 Nobel Prize for this reagent, which revolutionized organic synthesis." },
    { id: 105, topic: "Organic Chemistry", difficulty: "Hard", question: "What is the difference between E1 and E2 elimination?", options: ["E1 is first order, E2 is second order", "E1 requires a strong base, E2 doesn't", "E1 produces cis products, E2 produces trans", "There is no difference"], answer: 0, explanation: "E1 is a two-step unimolecular process (rate depends only on substrate). E2 is a one-step bimolecular process (rate depends on substrate and base).", funFact: "E2 elimination requires anti-periplanar geometry, meaning the H and leaving group must be on opposite sides." },

    // =================== 8. ELECTROCHEMISTRY (15) ===================
    // Easy (5)
    { id: 106, topic: "Electrochemistry", difficulty: "Easy", question: "What is oxidation?", options: ["Gain of electrons", "Loss of electrons", "Gain of protons", "Loss of neutrons"], answer: 1, explanation: "Oxidation is the loss of electrons. Remember: OIL RIG — Oxidation Is Loss, Reduction Is Gain.", funFact: "The term 'oxidation' originally referred to reactions with oxygen, but was later generalized to any electron loss." },
    { id: 107, topic: "Electrochemistry", difficulty: "Easy", question: "In an electrochemical cell, at which electrode does reduction occur?", options: ["Anode", "Cathode", "Both", "Neither"], answer: 1, explanation: "Reduction always occurs at the cathode. Think 'RED CAT' — Reduction at the Cathode.", funFact: "The word 'cathode' comes from Greek 'kathodos' meaning 'way down', referring to the current path." },
    { id: 108, topic: "Electrochemistry", difficulty: "Easy", question: "What is the charge of a Cu²⁺ ion?", options: ["-2", "+1", "+2", "0"], answer: 2, explanation: "Cu²⁺ has lost 2 electrons, giving it a charge of +2. It's commonly found in copper sulfate solutions (blue color).", funFact: "The blue color of copper sulfate solution is due to the [Cu(H₂O)₆]²⁺ complex ion." },
    { id: 109, topic: "Electrochemistry", difficulty: "Easy", question: "What type of cell converts chemical energy to electrical energy?", options: ["Electrolytic cell", "Galvanic (voltaic) cell", "Fuel cell only", "Solar cell"], answer: 1, explanation: "A galvanic (voltaic) cell converts chemical energy to electrical energy through spontaneous redox reactions. Batteries are examples.", funFact: "The first battery was invented by Alessandro Volta in 1800, using stacked zinc and copper discs." },
    { id: 110, topic: "Electrochemistry", difficulty: "Easy", question: "What is rusting?", options: ["Reduction of iron", "Oxidation of iron in the presence of water and oxygen", "Reaction of iron with nitrogen", "Melting of iron"], answer: 1, explanation: "Rusting is the oxidation of iron: 4Fe + 3O₂ + 6H₂O → 4Fe(OH)₃, which dehydrates to form rust (Fe₂O₃·xH₂O).", funFact: "Rust costs the US economy over $400 billion per year in damage and prevention." },

    // Medium (5)
    { id: 111, topic: "Electrochemistry", difficulty: "Medium", question: "What is the standard hydrogen electrode (SHE) potential?", options: ["-1.0 V", "0.0 V", "+1.0 V", "+0.5 V"], answer: 1, explanation: "The SHE is the reference electrode with a defined potential of exactly 0.00 V. All other standard electrode potentials are measured relative to it.", funFact: "The SHE uses platinum coated with platinum black dipped in 1 M H⁺ with H₂ gas at 1 atm." },
    { id: 112, topic: "Electrochemistry", difficulty: "Medium", question: "What does a positive cell potential (E°cell) indicate?", options: ["Non-spontaneous reaction", "Spontaneous reaction", "Equilibrium", "No reaction"], answer: 1, explanation: "A positive E°cell means ΔG° is negative (ΔG° = -nFE°), indicating a spontaneous reaction.", funFact: "A car battery has an E°cell of about 2V per cell, with 6 cells giving 12V total." },
    { id: 113, topic: "Electrochemistry", difficulty: "Medium", question: "In electrolysis of molten NaCl, what forms at the anode?", options: ["Sodium metal", "Chlorine gas", "Hydrogen gas", "Oxygen gas"], answer: 1, explanation: "At the anode (oxidation): 2Cl⁻ → Cl₂ + 2e⁻. At the cathode (reduction): Na⁺ + e⁻ → Na.", funFact: "This is how sodium metal is commercially produced — the Downs process." },
    { id: 114, topic: "Electrochemistry", difficulty: "Medium", question: "What is Faraday's first law of electrolysis?", options: ["Current is proportional to resistance", "Mass deposited is proportional to the charge passed", "Voltage determines the product", "All metals plate at the same rate"], answer: 1, explanation: "Faraday's first law: m = (MIt)/(nF), where m is mass deposited, M is molar mass, I is current, t is time, n is electrons transferred, F is Faraday's constant.", funFact: "Michael Faraday, a bookbinder's apprentice with no formal education, became one of history's greatest scientists." },
    { id: 115, topic: "Electrochemistry", difficulty: "Medium", question: "What is the salt bridge used for?", options: ["To mix the solutions", "To maintain electrical neutrality by allowing ion flow", "To increase voltage", "To speed up the reaction"], answer: 1, explanation: "The salt bridge allows migration of ions between half-cells to maintain electrical neutrality, completing the circuit without mixing solutions.", funFact: "Common salt bridge fillings include KCl or KNO₃ in agar gel." },

    // Hard (5)
    { id: 116, topic: "Electrochemistry", difficulty: "Hard", question: "Using the Nernst equation, what happens to cell potential when Q > K?", options: ["E increases", "E becomes negative", "E remains unchanged", "E equals E°"], answer: 1, explanation: "When Q > K, the reaction has gone past equilibrium. E = E° - (RT/nF)ln(Q). Since Q > K and E° = (RT/nF)ln(K), E becomes negative.", funFact: "The Nernst equation was developed by Walther Nernst, who also formulated the Third Law of Thermodynamics." },
    { id: 117, topic: "Electrochemistry", difficulty: "Hard", question: "How much charge (in Coulombs) is needed to deposit 1 mole of Cu from Cu²⁺?", options: ["96,485 C", "192,970 C", "48,243 C", "289,455 C"], answer: 1, explanation: "Cu²⁺ + 2e⁻ → Cu. Two moles of electrons needed. Charge = nF = 2 × 96,485 = 192,970 C.", funFact: "96,485 C/mol is Faraday's constant — the charge of one mole of electrons." },
    { id: 118, topic: "Electrochemistry", difficulty: "Hard", question: "What is overpotential?", options: ["Extra voltage from the battery", "Difference between theoretical and actual potential needed for electrolysis", "Voltage drop across the salt bridge", "Potential of the standard cell"], answer: 1, explanation: "Overpotential is the extra voltage beyond the thermodynamic requirement needed to drive an electrode reaction at a practical rate, due to kinetic barriers.", funFact: "Overpotential is why water electrolysis requires ~1.8V instead of the theoretical 1.23V." },
    { id: 119, topic: "Electrochemistry", difficulty: "Hard", question: "In a concentration cell, what drives the reaction?", options: ["Different metals at each electrode", "Different concentrations of the same electrolyte", "An external power source", "Different temperatures"], answer: 1, explanation: "A concentration cell uses the same electrode material but different electrolyte concentrations. The potential arises from the concentration gradient, driving ions from high to low concentration.", funFact: "Biological nerve cells use concentration gradients of Na⁺ and K⁺ to generate electrical signals." },
    { id: 120, topic: "Electrochemistry", difficulty: "Hard", question: "What is the standard cell potential for: Zn(s) | Zn²⁺ || Cu²⁺ | Cu(s), given E°(Zn²⁺/Zn) = -0.76V and E°(Cu²⁺/Cu) = +0.34V?", options: ["+0.42V", "+1.10V", "-0.42V", "-1.10V"], answer: 1, explanation: "E°cell = E°cathode - E°anode = 0.34 - (-0.76) = +1.10V. Zinc is oxidized (anode), copper is reduced (cathode).", funFact: "This is the Daniel cell, invented in 1836 and one of the first reliable batteries." },

    // =================== 9. NUCLEAR CHEMISTRY (15) ===================
    // Easy (5)
    { id: 121, topic: "Nuclear Chemistry", difficulty: "Easy", question: "What is radioactivity?", options: ["Emission of light", "Spontaneous emission of radiation from unstable nuclei", "Chemical reaction with radium", "Absorption of X-rays"], answer: 1, explanation: "Radioactivity is the spontaneous emission of particles or energy from unstable atomic nuclei as they seek a more stable configuration.", funFact: "Henri Becquerel discovered radioactivity accidentally in 1896 when uranium salts fogged his photographic plates." },
    { id: 122, topic: "Nuclear Chemistry", difficulty: "Easy", question: "What type of radiation is a helium nucleus?", options: ["Beta particle", "Alpha particle", "Gamma ray", "Neutron"], answer: 1, explanation: "An alpha particle consists of 2 protons and 2 neutrons — identical to a helium-4 nucleus (⁴₂He).", funFact: "Alpha particles can be stopped by a sheet of paper or even a few centimeters of air." },
    { id: 123, topic: "Nuclear Chemistry", difficulty: "Easy", question: "What is half-life?", options: ["The time for all atoms to decay", "The time for half the radioactive atoms to decay", "Half the lifetime of an atom", "The time for the radiation to halve in energy"], answer: 1, explanation: "Half-life (t₁/₂) is the time required for half the radioactive nuclei in a sample to undergo decay.", funFact: "Bismuth-209 has the longest known half-life: about 1.9 × 10¹⁹ years — a billion times the age of the universe!" },
    { id: 124, topic: "Nuclear Chemistry", difficulty: "Easy", question: "What is nuclear fission?", options: ["Combining light nuclei", "Splitting a heavy nucleus into smaller nuclei", "Neutron absorption without splitting", "Electron capture"], answer: 1, explanation: "Nuclear fission is the splitting of a heavy nucleus (like U-235) into two or more lighter nuclei, releasing enormous energy.", funFact: "The energy from 1 kg of uranium fission equals about 3 million kg of coal combustion." },
    { id: 125, topic: "Nuclear Chemistry", difficulty: "Easy", question: "Which type of radiation has the highest penetrating power?", options: ["Alpha", "Beta", "Gamma", "All equal"], answer: 2, explanation: "Gamma rays (electromagnetic radiation) have the highest penetrating power, requiring thick lead or concrete to stop.", funFact: "Gamma rays from space are blocked by Earth's atmosphere — which is why gamma-ray telescopes must orbit in space." },

    // Medium (5)
    { id: 126, topic: "Nuclear Chemistry", difficulty: "Medium", question: "What particle is emitted during beta-minus (β⁻) decay?", options: ["Proton", "Electron", "Positron", "Alpha particle"], answer: 1, explanation: "In β⁻ decay, a neutron converts to a proton and emits an electron (β⁻ particle) and an antineutrino: n → p + e⁻ + ν̄.", funFact: "The neutrino emitted in beta decay was predicted by Pauli in 1930 but not detected until 1956." },
    { id: 127, topic: "Nuclear Chemistry", difficulty: "Medium", question: "What is nuclear fusion?", options: ["Splitting heavy atoms", "Combining light nuclei to form heavier ones", "Radioactive decay", "Neutron bombardment"], answer: 1, explanation: "Nuclear fusion combines light nuclei (like hydrogen) to form heavier ones (like helium), releasing energy. This powers the Sun.", funFact: "The Sun fuses about 600 million tonnes of hydrogen into helium every second." },
    { id: 128, topic: "Nuclear Chemistry", difficulty: "Medium", question: "After 3 half-lives, what fraction of the original radioactive sample remains?", options: ["1/2", "1/4", "1/8", "1/16"], answer: 2, explanation: "After each half-life, half remains: 1 → 1/2 → 1/4 → 1/8. After 3 half-lives, 1/8 (12.5%) remains.", funFact: "After 10 half-lives, only about 0.1% of the original sample remains." },
    { id: 129, topic: "Nuclear Chemistry", difficulty: "Medium", question: "What is carbon-14 dating used for?", options: ["Dating rocks billions of years old", "Dating organic materials up to ~50,000 years old", "Measuring radiation exposure", "Determining atomic mass"], answer: 1, explanation: "Carbon-14 dating measures the ratio of ¹⁴C to ¹²C in organic remains. ¹⁴C has a half-life of 5,730 years, useful for dating up to ~50,000 years.", funFact: "Willard Libby won the Nobel Prize in 1960 for developing radiocarbon dating." },
    { id: 130, topic: "Nuclear Chemistry", difficulty: "Medium", question: "What is a chain reaction in nuclear fission?", options: ["A reaction that stops after one step", "Each fission event triggers one or more additional fissions", "A reaction requiring continuous energy input", "A reaction that only occurs in stars"], answer: 1, explanation: "In a chain reaction, neutrons released from one fission event cause additional fissions, potentially creating an exponential cascade.", funFact: "The first controlled chain reaction was achieved by Enrico Fermi under the stands of a Chicago football stadium in 1942." },

    // Hard (5)
    { id: 131, topic: "Nuclear Chemistry", difficulty: "Hard", question: "What is binding energy per nucleon?", options: ["Energy to remove one electron", "Energy to completely separate a nucleus into individual protons and neutrons, divided by the number of nucleons", "Energy of a gamma ray", "Energy of radioactive decay"], answer: 1, explanation: "Binding energy per nucleon measures nuclear stability. Iron-56 has the highest value (~8.8 MeV/nucleon), making it the most stable nucleus.", funFact: "This is why fusion of light elements and fission of heavy elements both release energy — both move toward iron on the curve." },
    { id: 132, topic: "Nuclear Chemistry", difficulty: "Hard", question: "What is the mass defect?", options: ["Error in mass measurement", "Difference between the sum of individual nucleon masses and actual nuclear mass", "Mass lost during chemical reactions", "Mass of an electron"], answer: 1, explanation: "The mass defect (Δm) is the difference between the total mass of separate nucleons and the actual mass of the nucleus. This 'missing' mass is converted to binding energy via E = mc².", funFact: "For helium-4, the mass defect is about 0.03 u, corresponding to 28.3 MeV of binding energy." },
    { id: 133, topic: "Nuclear Chemistry", difficulty: "Hard", question: "What is the Q-value of a nuclear reaction?", options: ["Charge of the products", "Energy released or absorbed in the reaction", "Number of neutrons produced", "Ratio of reactant masses"], answer: 1, explanation: "Q = (mass of reactants - mass of products) × c². Positive Q means energy is released (exothermic); negative Q means energy is absorbed.", funFact: "The Q-value for deuterium-tritium fusion is 17.6 MeV — the basis for fusion reactor research." },
    { id: 134, topic: "Nuclear Chemistry", difficulty: "Hard", question: "What is the critical mass?", options: ["Mass at which fusion begins", "Minimum mass of fissile material needed to sustain a chain reaction", "Maximum mass before collapse", "Mass of the moderator"], answer: 1, explanation: "Critical mass is the minimum amount of fissile material (e.g., U-235 or Pu-239) needed for a self-sustaining chain reaction, where neutron production ≥ neutron loss.", funFact: "The critical mass of U-235 as a bare sphere is about 52 kg, but neutron reflectors can reduce this significantly." },
    { id: 135, topic: "Nuclear Chemistry", difficulty: "Hard", question: "What is the purpose of a moderator in a nuclear reactor?", options: ["To speed up neutrons", "To slow down neutrons to increase fission probability", "To absorb all radiation", "To cool the reactor only"], answer: 1, explanation: "Moderators (like water, heavy water, or graphite) slow fast neutrons to thermal energies, greatly increasing their probability of causing U-235 fission.", funFact: "The first nuclear reactor (Chicago Pile-1) used 385 tons of graphite as its moderator." },

    // =================== 10. ENVIRONMENTAL CHEMISTRY (15) ===================
    // Easy (5)
    { id: 136, topic: "Environmental Chemistry", difficulty: "Easy", question: "What is the main greenhouse gas produced by human activities?", options: ["Oxygen", "Nitrogen", "Carbon dioxide", "Argon"], answer: 2, explanation: "CO₂ is the primary anthropogenic greenhouse gas, mainly from burning fossil fuels, deforestation, and industrial processes.", funFact: "Atmospheric CO₂ levels have risen from ~280 ppm before the Industrial Revolution to over 420 ppm today." },
    { id: 137, topic: "Environmental Chemistry", difficulty: "Easy", question: "What causes acid rain?", options: ["Excess CO₂ only", "SO₂ and NOₓ emissions dissolving in rainwater", "Volcanic dust", "Ocean evaporation"], answer: 1, explanation: "Acid rain forms when SO₂ and NOₓ from fossil fuel combustion react with water vapor to form sulfuric and nitric acids.", funFact: "Normal rain is already slightly acidic (pH ~5.6) due to dissolved CO₂ forming carbonic acid." },
    { id: 138, topic: "Environmental Chemistry", difficulty: "Easy", question: "What layer of the atmosphere contains the ozone layer?", options: ["Troposphere", "Stratosphere", "Mesosphere", "Thermosphere"], answer: 1, explanation: "The ozone layer is found in the stratosphere, roughly 15-35 km above Earth's surface, where it absorbs UV radiation.", funFact: "If all the ozone in the stratosphere were compressed to sea-level pressure, it would be only about 3 mm thick." },
    { id: 139, topic: "Environmental Chemistry", difficulty: "Easy", question: "What is the chemical formula for ozone?", options: ["O", "O₂", "O₃", "O₄"], answer: 2, explanation: "Ozone (O₃) consists of three oxygen atoms. It's an allotrope of oxygen that absorbs harmful UV-B and UV-C radiation.", funFact: "Ozone has a distinctive smell — the word 'ozone' comes from the Greek 'ozein' meaning 'to smell'." },
    { id: 140, topic: "Environmental Chemistry", difficulty: "Easy", question: "What is the process of water purification called when using chlorine?", options: ["Filtration", "Chlorination", "Distillation", "Crystallization"], answer: 1, explanation: "Chlorination adds chlorine or chlorine compounds to water to kill bacteria and other microorganisms, making water safe to drink.", funFact: "Chlorination of drinking water is considered one of the greatest public health achievements of the 20th century." },

    // Medium (5)
    { id: 141, topic: "Environmental Chemistry", difficulty: "Medium", question: "What chemical depletes the ozone layer?", options: ["CO₂", "CFCs (chlorofluorocarbons)", "CH₄", "N₂O"], answer: 1, explanation: "CFCs release chlorine atoms in the stratosphere that catalytically destroy ozone. One chlorine atom can destroy ~100,000 ozone molecules.", funFact: "The Montreal Protocol (1987) banning CFCs is considered the most successful environmental treaty ever." },
    { id: 142, topic: "Environmental Chemistry", difficulty: "Medium", question: "What is BOD (Biochemical Oxygen Demand)?", options: ["Amount of oxygen in a water body", "Amount of oxygen needed by microorganisms to decompose organic matter", "Oxygen produced by photosynthesis", "Oxygen in the atmosphere"], answer: 1, explanation: "BOD measures the oxygen consumed by microorganisms to break down organic pollutants in water. High BOD indicates heavy organic pollution.", funFact: "Clean river water typically has a BOD of less than 2 mg/L, while raw sewage can exceed 300 mg/L." },
    { id: 143, topic: "Environmental Chemistry", difficulty: "Medium", question: "What is the greenhouse effect?", options: ["Plants growing in greenhouses", "Trapping of heat by atmospheric gases", "Reflection of sunlight by ice", "Cooling of the atmosphere"], answer: 1, explanation: "The greenhouse effect occurs when atmospheric gases (CO₂, CH₄, H₂O, N₂O) absorb and re-emit infrared radiation, warming the Earth's surface.", funFact: "Without the natural greenhouse effect, Earth's average temperature would be about -18°C instead of +15°C." },
    { id: 144, topic: "Environmental Chemistry", difficulty: "Medium", question: "What is eutrophication?", options: ["Water becoming more acidic", "Excessive nutrient enrichment causing algal blooms", "Water evaporation", "Salt accumulation in soil"], answer: 1, explanation: "Eutrophication occurs when excess nitrogen and phosphorus (from fertilizers, sewage) cause rapid algal growth, which depletes oxygen and kills aquatic life.", funFact: "The 'Dead Zone' in the Gulf of Mexico, caused by Mississippi River nutrient runoff, can be as large as New Jersey." },
    { id: 145, topic: "Environmental Chemistry", difficulty: "Medium", question: "What is the main component of photochemical smog?", options: ["Carbon monoxide", "Ground-level ozone", "Sulfur dioxide", "Particulate matter"], answer: 1, explanation: "Photochemical smog contains ground-level ozone (O₃) formed when NOₓ and VOCs react in sunlight. Unlike stratospheric ozone, this is harmful.", funFact: "Los Angeles was the first city to experience severe photochemical smog in the 1940s." },

    // Hard (5)
    { id: 146, topic: "Environmental Chemistry", difficulty: "Hard", question: "What is the Global Warming Potential (GWP) of methane relative to CO₂ over 100 years?", options: ["1", "10-12", "28-36", "265-298"], answer: 2, explanation: "Methane's 100-year GWP is about 28-36 (IPCC AR5), meaning it traps 28-36 times more heat than the same mass of CO₂ over 100 years.", funFact: "Over 20 years, methane's GWP is about 84-87, as it's initially much more potent but breaks down faster than CO₂." },
    { id: 147, topic: "Environmental Chemistry", difficulty: "Hard", question: "What is biomagnification?", options: ["Growth of organisms due to nutrients", "Increasing concentration of toxins up the food chain", "Magnification of cells under a microscope", "Amplification of biological signals"], answer: 1, explanation: "Biomagnification is the increasing concentration of persistent pollutants (like DDT, mercury, PCBs) at each successive trophic level in a food chain.", funFact: "DDT biomagnification caused eggshell thinning in birds of prey, leading to Rachel Carson's 'Silent Spring' and the eventual DDT ban." },
    { id: 148, topic: "Environmental Chemistry", difficulty: "Hard", question: "What is the chemical reaction for the catalytic destruction of ozone by chlorine?", options: ["Cl + O₃ → ClO + O₂, then ClO + O → Cl + O₂", "Cl₂ + O₃ → 2ClO + O", "CFC + O₃ → CO₂ + ClF", "Cl + O₂ → ClO₂"], answer: 0, explanation: "The catalytic cycle: Cl + O₃ → ClO + O₂, then ClO + O → Cl + O₂. The net result is O₃ + O → 2O₂, with Cl regenerated as a catalyst.", funFact: "Mario Molina and F. Sherwood Rowland won the 1995 Nobel Prize for discovering this CFC-ozone mechanism." },
    { id: 149, topic: "Environmental Chemistry", difficulty: "Hard", question: "What is the primary chemical process in a catalytic converter?", options: ["Reducing CO₂ to carbon", "Oxidizing CO and hydrocarbons while reducing NOₓ", "Filtering particulate matter", "Absorbing SO₂"], answer: 1, explanation: "A three-way catalytic converter: 1) oxidizes CO → CO₂, 2) oxidizes unburnt hydrocarbons → CO₂ + H₂O, 3) reduces NOₓ → N₂ + O₂, using Pt, Pd, and Rh catalysts.", funFact: "The platinum-group metals in a catalytic converter are so valuable that converter theft has become a significant crime problem." },
    { id: 150, topic: "Environmental Chemistry", difficulty: "Hard", question: "What is the significance of the Keeling Curve?", options: ["It shows decreasing ocean pH", "It records rising atmospheric CO₂ concentrations since 1958", "It maps ozone depletion", "It tracks global temperature changes"], answer: 1, explanation: "The Keeling Curve, started by Charles David Keeling at Mauna Loa, shows the continuous rise of atmospheric CO₂ with seasonal oscillations, becoming an icon of climate science.", funFact: "The seasonal oscillation in the Keeling Curve is caused by Northern Hemisphere vegetation — effectively, the Earth 'breathing'." }
];

